def _capture_role(module, role, signature):
    from .timeline_temporal_live_scope import _function_tree, _render_wrapper_original
    function = _resolve(module, role)
    if module.__name__ == 'src.engine.playback_engine' and role == 'PlaybackEngine._render_position':
        if not _render_wrapper_original(function):
            return None
        qualified = vars(function).get('__wrapped__')
    elif module.__name__ == 'src.engine.timeline_temporal_replay' and role == '_original_frame_shadow':
        context = sys.modules.get('contextlib')
        wrapper_pin = EXPECTED.get('contextlib', {}).get('contextmanager.<locals>.helper')
        if (context is None or wrapper_pin is None
                or not _canonical(function, context, wrapper_pin)
                or function.__defaults__ is not None or function.__kwdefaults__ is not None):
            return None
        qualified = vars(function).get('__wrapped__')
        cells = dict(zip(function.__code__.co_freevars,
                         (cell.cell_contents for cell in function.__closure__ or ())))
        if cells.get('func') is not qualified:
            return None
    elif type(function) is builtins.property:
        # Require the original property prototype and the real getter body.
        # Do not remove required attributes or capture an empty descriptor tree.
        qualified = function.fget
    else:
        qualified = function
    defaults = DEFAULTS.get((module.__name__, role))
    if (defaults is None or not _canonical(qualified, module, signature)
            or qualified.__defaults__ != defaults[0]
            or qualified.__kwdefaults__ != defaults[1]):
        return None
    namespace = vars(module)
    rows = []
    for part in role.split('.')[:-1]:
        rows.append((namespace, part, namespace[part]))
        namespace = vars(namespace[part])
    # Preserve actual class namespace values, including staticmethod wrappers.
    rows.append((namespace, role.split('.')[-1], namespace[role.split('.')[-1]]))
    rows.extend(_function_tree(qualified if type(function) is builtins.property else function, set()))
    if module.__name__ == 'src.engine.timeline_temporal_replay' and role == '_original_frame_shadow':
        rows.extend(((sys.modules, 'contextlib', context),
                     (EXPECTED['contextlib'], 'contextmanager.<locals>.helper', wrapper_pin)))
    rows.append((DEFAULTS, (module.__name__, role), defaults))
    if qualified.__kwdefaults__ is not None:
        rows.extend((qualified.__kwdefaults__, key, value)
                    for key, value in qualified.__kwdefaults__.items())
    return rows


def _thread_rows():
    global _THREAD_CERTIFICATE
    module, raw = sys.modules.get('threading'), sys.modules.get('_thread')
    expected = EXPECTED.get('threading', {})
    roles = ('current_thread', '_DummyThread.__init__', 'Thread.__init__')
    if module is None or raw is None or any(not expected.get(role) for role in roles):
        return None
    if _THREAD_CERTIFICATE is not None:
        return _THREAD_CERTIFICATE if metadata_current(_THREAD_CERTIFICATE) else None
    ident = vars(module).get('get_ident')
    if (type(ident) is not BuiltinFunctionType or ident.__module__ != '_thread'
            or ident.__name__ != 'get_ident' or vars(raw).get('get_ident') is not ident):
        return None
    rows = [(sys.modules, 'threading', module), (sys.modules, '_thread', raw),
            (EXPECTED, 'threading', expected), (vars(module), 'get_ident', ident),
            (vars(raw), 'get_ident', ident)]
    for role in roles:
        captured = _capture_role(module, role, expected[role])
        if captured is None:
            return None
        rows.extend(captured)
        rows.append((expected, role, expected[role]))
    current = vars(module)['current_thread']
    if (type(vars(module).get('_active')) is not dict
            or current.__builtins__ is not vars(builtins)
            or vars(module).get('KeyError', builtins.KeyError) is not builtins.KeyError):
        return None
    for name in ('_active', '_DummyThread', 'Thread'):
        rows.append((vars(module), name, vars(module)[name]))
    rows.extend(((vars(module), 'KeyError', vars(module).get('KeyError')),
                 (vars(builtins), 'KeyError', builtins.KeyError)))
    _THREAD_CERTIFICATE = tuple(rows)
    return _THREAD_CERTIFICATE


def thread_source_current():
    # Initial acceptance uses ROOT's independent trusted-stdlib source pins.
    # A foreign current_thread callable is never learned as the new baseline.
    return _thread_rows() is not None


def _stock_aliases_current(module):
    for alias, name in (('sys', 'sys'), ('ct', 'ctypes'), ('time', 'time'),
                        ('threading', 'threading')):
        value = vars(module).get(alias)
        if value is not None and sys.modules.get(name) is not value:
            return False
    if vars(module).get('threading') is not None and not thread_source_current():
        return False
    clock_module = vars(module).get('time')
    if clock_module is None:
        return True
    for name in ('monotonic', 'monotonic_ns'):
        function = vars(clock_module).get(name)
        if (type(function) is not BuiltinFunctionType or function.__name__ != name
                or function.__module__ != 'time'):
            return False
    return True


def _capture_aliases(module):
    if not _stock_aliases_current(module):
        return None
    rows = []
    for alias in ('sys', 'ct', 'time', 'threading', 'ContextVar', 'native_binding',
                  'outer_owns_lock', 'claim_outer_lock', 'retire_outer_lock',
                  'replay_owns_lock', 'acquire_render_lock', 'release_render_lock',
                  'source_current', 'local_render_transaction', 'has_local_owner',
                  'borrow_local_frame', 'return_local_frame', 'prepare_ready_frame',
                  'apply_ready_exit', 'finish_ready_frame', 'reject_ready_source',
                  'render_timing_math', '_resolve', '_canonical', 'metadata_current',
                  'function_metadata'):
        value = vars(module).get(alias)
        if value is not None:
            rows.append((vars(module), alias, value))
            if type(value) is FunctionType:
                rows.extend(function_metadata(value))
            for member in ('monotonic', 'monotonic_ns', 'get_ident', 'current_thread',
                           'byref', 'cast', 'sizeof', 'bind_native'):
                captured = vars(value).get(member) if hasattr(value, '__dict__') else None
                if captured is not None:
                    rows.append((vars(value), member, captured))
                    if type(captured) is FunctionType:
                        rows.extend(function_metadata(captured))
    for field in ('_LOCAL', '_OUTER_RENDER_OWNER', '_OWNED_REPLAY', '_READY_FIELDS'):
        if field in vars(module):
            rows.append((vars(module), field, vars(module)[field]))
    scope = sys.modules.get('src.engine.timeline_temporal_live_scope')
    if scope is not None:
        for name in ('_function_tree', '_render_wrapper_original', '_PROJECT_WRAPPER'):
            value = vars(scope).get(name)
            rows.append((vars(scope), name, value))
            if type(value) is FunctionType:
                rows.extend(function_metadata(value))
    return rows


def _capture_module(name, expected):
    from .timeline_sntc_signatures import EXPECTED as original
    module = sys.modules.get(name)
    mandatory = set(MINIMUM[name]) | set(original.get(name, ()))
    if module is None or not mandatory.issubset(expected):
        return None
    rows = [(sys.modules, name, module), (EXPECTED, name, expected),
            (MINIMUM, name, MINIMUM[name])]
    for role, signature in expected.items():
        if '<locals>' in role:
            policy = DEFAULTS.get((name, role))
            if policy != ('controller-bound', None):
                return None
            rows.extend(((expected, role, signature), (DEFAULTS, (name, role), policy)))
            continue
        captured = _capture_role(module, role, signature)
        if captured is None:
            return None
        rows.extend(captured)
        rows.append((expected, role, signature))
    aliases = _capture_aliases(module)
    if aliases is None:
        return None
    rows.extend(aliases)
    return rows


def _domain_rows(names, flag):
    if globals().get(flag) is not True or any(not EXPECTED.get(name) for name in names):
        return None
    threads = _thread_rows()
    if threads is None:
        return None
    rows = [(globals(), flag, True), (globals(), 'EXPECTED', EXPECTED),
            (globals(), 'DEFAULTS', DEFAULTS), (globals(), 'REQUIRED', REQUIRED),
            (globals(), 'RENDER_REQUIRED', RENDER_REQUIRED),
            (globals(), 'TRANSPORT_REQUIRED', TRANSPORT_REQUIRED), (globals(), 'MINIMUM', MINIMUM)]
    rows.extend(threads)
    for name in names:
        captured = _capture_module(name, EXPECTED[name])
        if captured is None:
            return None
        rows.extend(captured)
    engine = vars(sys.modules['src.engine.playback_engine'])
    ready = vars(sys.modules['src.engine.timeline_ready_cache_source'])
    if any(engine.get(name) is not ready.get(name)
           for name in ('acquire_render_lock', 'release_render_lock')):
        return None
    return tuple(rows)


def render_scope_rows():
    global _RENDER_CERTIFICATE
    if RENDER_ENABLED is not True:
        return None
    if _RENDER_CERTIFICATE is None:
        _RENDER_CERTIFICATE = _domain_rows(RENDER_REQUIRED, 'RENDER_ENABLED')
    return _RENDER_CERTIFICATE if metadata_current(_RENDER_CERTIFICATE) else None


def admitted_rows():
    global _CERTIFICATE
    if ENABLED is not True or render_scope_rows() is None:
        return None
    if _CERTIFICATE is None:
        _CERTIFICATE = _domain_rows(REQUIRED, 'ENABLED')
    return _CERTIFICATE if metadata_current(_CERTIFICATE) else None


def transport_scope_rows():
    global _TRANSPORT_CERTIFICATE
    if render_scope_rows() is None:
        return None
    if _TRANSPORT_CERTIFICATE is None:
        _TRANSPORT_CERTIFICATE = _domain_rows(TRANSPORT_REQUIRED, 'RENDER_ENABLED')
    return _TRANSPORT_CERTIFICATE if metadata_current(_TRANSPORT_CERTIFICATE) else None


def successor_module_rows(name):
    """Changed roles cannot fall back to an old pin or a partial successor."""
    if name in RENDER_REQUIRED:
        return True, render_scope_rows()
    if name in TRANSPORT_REQUIRED:
        return True, transport_scope_rows()
    if name not in REQUIRED:
        return False, None
    return True, admitted_rows()


def successor_render_current(function, owner):
    rows = render_scope_rows()
    module = sys.modules.get('src.engine.playback_engine')
    return (rows is not None and module is not None
            and vars(module).get('PlaybackEngine') is owner
            and vars(vars(owner).get('_render_position')).get('__wrapped__') is function)


def class_role_names(name):
    from .timeline_sntc_signatures import EXPECTED as original
    return tuple(EXPECTED.get(name, ())) if name in REQUIRED else tuple(original.get(name, ()))


def clock_source_current(callback):
    module = sys.modules.get('src.ui.main_window')
    role = getattr(getattr(callback, '__code__', None), 'co_qualname', '')
    wanted = EXPECTED.get('src.ui.main_window', {}).get(role)
    defaults = getattr(callback, '__defaults__', None)
    if (transport_scope_rows() is None or wanted is None or module is None
            or DEFAULTS.get((module.__name__, role)) != ('controller-bound', None)
            or type(defaults) is not tuple or len(defaults) != 1):
        return False
    controller = defaults[0]
    owner = sys.modules.get('src.ui.timeline.timeline_controller')
    return (owner is not None and type(controller) is vars(owner).get('TimelineController')
            and callback.__kwdefaults__ is None and _canonical(callback, module, wanted)
            and callback.__globals__.get('vars', builtins.vars) is builtins.vars)


def source_current(bridge):
    binding = vars(bridge).get('_local_clock')
    module = sys.modules.get('qascade_ce.native_sntc_local_clock')
    if (module is None or type(binding) is not vars(module).get('LocalClockBinding')
            or binding._base is not vars(bridge).get('_native')
            or not binding.source_current()):
        return False
    roles = EXPECTED.get('src.ui.sntc_sync_binding', ())
    if any(role.rsplit('.', 1)[-1] in vars(bridge) for role in roles
           if role.startswith('SntcTimelineBridge.')):
        return False
    return bridge.source_current()


